.map_err(|error| {
    let reason = error.details.as_slice().first().filter(|detail| {
        error.details.len() == 1 && detail.kind == "admission.currentness" && detail.fields.len() == 1
    }).and_then(|detail| detail.fields.get("reason"))
      .filter(|value| latent_core::error::ADMISSION_CURRENTNESS_REASONS.contains(&value.as_str()))
      .map_or("unknown", String::as_str);
    eprintln!("LSF-PRIVATE-STARTUP {}", serde_json::json!({
        "schemaVersion": "lsf.private.startup-diagnostic.v1",
        "code": error.code.wire_code(), "retryable": error.retryable,
        "detailCount": error.details.len().min(16), "currentnessReason": reason,
        "exactBookkeepingBusy": error.code == PlatformErrorCode::Unavailable
            && error.retryable && reason == "admission-authority-busy"
    }));
    Failure::new("startup", error.code)
})?;
